import assert from 'node:assert/strict';
import { createSubmitHandler } from './submit.mjs';
let release;
let calls = 0;
let prevented = 0;
const states = [];
const event = { preventDefault() { prevented++; } };
const submit = createSubmitHandler(() => { calls++; return new Promise(resolve => { release = resolve; }); }, value => states.push(value));
const pending = submit(event);
assert.ok(pending instanceof Promise);
await submit(event);
assert.equal(calls, 1);
assert.equal(prevented, 2);
assert.deepEqual(states, [true]);
release();
await pending;
assert.deepEqual(states, [true, false]);
const retry = submit(event);
assert.equal(calls, 2);
release();
await retry;
for (const synchronous of [false, true]) {
  const error = new Error('save failed');
  const states = [];
  let calls = 0;
  const submit = createSubmitHandler(() => {
    calls++;
    if (calls > 1) return;
    if (synchronous) throw error;
    return Promise.reject(error);
  }, value => states.push(value));
  await assert.rejects(submit(event), actual => actual === error);
  assert.deepEqual(states, [true, false]);
  await submit(event);
  assert.equal(calls, 2);
  assert.deepEqual(states, [true, false, true, false]);
}
console.log('Passed: concurrent save guard, busy cleanup, error propagation, and retries.');
