export function createSubmitHandler(save, setBusy) {
  let busy = false;

  return async function submit(event) {
    event.preventDefault();
    if (busy) return;

    busy = true;
    try {
      setBusy(true);
      await save();
    } finally {
      busy = false;
      setBusy(false);
    }
  };
}
